(1915, 1, 'Translate sentences 2 (Vocabulary)', NULL, 49, '', '<h3>PĹeloÂte!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>Honza took a fast shower.</i></p>        </td>        <td vAlign=\"top\" width=\"360\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>Yesterday, I studied for a long time.</i></p>        </td>        <td vAlign=\"top\" width=\"360\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>Hana is well.</i></p>        </td>        <td vAlign=\"top\" width=\"360\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>Usually, he got up at 6.</i></p>        </td>        <td vAlign=\"top\" width=\"360\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>They came to school on foot.</i></p>        </td>        <td vAlign=\"top\" width=\"360\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>You speak excellent English.</i></p>        </td>        <td vAlign=\"top\" width=\"360\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>I wrote the exercise badly?</i></p>        </td>        <td vAlign=\"top\" width=\"360\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>It is nice of you.</i></p>        </td>        <td vAlign=\"top\" width=\"360\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"243\">          <p><i>Please, speak slowly.</i></p>        </td>        <td vAlign=\"top\" width=\"360\">          <p> [$1, text 40] </p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1916, 1, 'Translate sentences 3 (Vocabulary)', NULL, 49, '', '<h3>PĹeloÂte!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>He likes my sister.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>I don\'t know your father.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>We need our books now.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>She likes his friend.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>They called their friends.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>I like his job.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>He likes his job.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>He likes my job.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"196\">          <p><i>I like my job.</i></p>        </td>        <td vAlign=\"top\" width=\"407\">          <p> [$1, text 40] </p>        </td>      </tr>    </t