(1918, 1, 'Translate sentences 5 (Vocabulary)', NULL, 49, '', '<h3>PĹeloÂte!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I like to watch TV.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>My wife likes to look at young men.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I will never forget you!</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Excuse me. I forgot all about it.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Who are you waiting for?</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I am waiting for two our teachers.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I rely on you, Mrs. VeselĂĄ.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>We could not rely on anybody.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>    </tbody>  </table>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I will definitely get it!</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Parents think about you.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Think of Henry!</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I am in the Czech Republic for two years.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Czech students often go for a year to America.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\"> [$1, text 60] </td>      </tr>    </tbody>  </table>   ', 3, ''),
