(2051, 1, 'U37/10  DoplĹte prepozice!', 'do, k, na, u, vedle. blĂ­zko, bez, v', 58, '', '<H3><FONT color=#330099>DoplĹte prepozice!</FONT></H3>\r\n<P><FONT color=#330099>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 width=\"100%\" align=left bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD>&nbsp;<I><FONT color=#330099>RĂĄno chodĂ­m [$1,text 5:do] Âkoly. Odpoledne chodĂ­m plavat [$1,text 5:do] bazĂŠnu. VeÄer chodĂ­m [$1,text 5:do] kina nebo [$1,text 5:do] divadla. ObÄas jdu [$1,text 5:ke] kamarĂĄdce AlenÄ. ÄekĂĄme [$1,text 5:na] Janu [$1,text 5:na] nĂĄdraÂĂ­. Co si dĂĄte [$1,text 5:k&nbsp;] veÄeĹi? Michal a David jsou [$1,text 5:z]&nbsp;ÄeskĂŠho Krumlova. Dnes veÄer jdeme [$1,text 5:do] restaurace. PoÂta je [$1,text 5:u, vedle, blĂ­zko] hotelu. ProsĂ­m kĂĄvu [$1,text 5:bez] mlĂŠka. JezdĂ­te [$1,text 5:na] vĂ˝lety? [$1,text 5:V]&nbsp;kolik hodin je ÄeÂtina? MusĂ­te jĂ­t rovnÄ [$1,text 5:na] nĂĄmÄstĂ­. [$1,text 5:V]&nbsp;pĂĄtek jedeme [$1,text 5:do] BudapeÂti. Dneska veÄer jdeme [$1,text 5:na] diskotĂŠku. Renata je [$1,text 5:u] Pavla. Jirka jde [$1,text 5:k]&nbsp;Pavle. Jdu [$1,text 5:do] hospody [$1,text 5:u, vedle, blĂ­zko] divadla. RĂĄno nejdeme [$1,text 5:na] vĂ˝stavu.</FONT></I></TD></TR></TBODY></TABLE></FONT></P>', 3, NULL),
(2052, 1, 'U17/1', '', 58, '', '<H3 align=left><FONT color=#330099>Poslouchejte dialog!</FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#ffffcc border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>ProdavaÄ:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>DobrĂ˝ den! PĹejete si, prosĂ­m?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>ZĂĄkaznĂ­k:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>DobrĂ˝ den! ÄtyĹi kolĂĄÄky,prosĂ­m.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>ProdavaÄ:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>JeÂtÄ nÄco?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>ZĂĄkaznĂ­k:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Ano, dvÄ koly a salĂĄt.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>ProdavaÄ:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>JakĂ˝?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>ZĂĄkaznĂ­k:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>KuĹecĂ­.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>ProdavaÄ:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>A kolik?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>ZĂĄkaznĂ­k:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Dvacet deka</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>ProdavaÄ:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Je to vÂechno?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>ZĂ